const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time periods
  const naivasha = ee.Geometry.Point([36.4333, -0.7167]).buffer(15000); // 15km radius

  // 2. Cloud masking function for Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
      .and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // 3. Function to calculate urban area using NDBI and NDVI
  function calculateUrban(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    const ndbi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
    // Urban: NDBI > 0 and NDVI < 0.2
    const urban = ndbi.gt(0).and(ndvi.lt(0.2));
    return urban;
  }

  // 4. Get 1986 data (Landsat 5)
  let col1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(naivasha)
    .filterDate('1986-01-01', '1986-12-31')
    .map(maskL5Clouds);

  const size1986 = await col1986.size().getInfo();
  console.log(`1986 Images: ${size1986}`);

  if (size1986 === 0) {
    console.log('No data for 1986');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Get 2000 data (Landsat 5 or 7)
  let col2000 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(naivasha)
    .filterDate('2000-01-01', '2000-12-31')
    .map(maskL5Clouds);

  let size2000 = await col2000.size().getInfo();

  if (size2000 === 0) {
    col2000 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(naivasha)
      .filterDate('2000-01-01', '2000-12-31')
      .map(maskL5Clouds);
    size2000 = await col2000.size().getInfo();
  }

  console.log(`2000 Images: ${size2000}`);

  if (size2000 === 0) {
    console.log('No data for 2000');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Create median composites
  const img1986 = col1986.median();
  const img2000 = col2000.median();

  // 7. Calculate urban areas
  const urban1986 = calculateUrban(img1986);
  const urban2000 = calculateUrban(img2000);

  // 8. Calculate pixel counts
  const stats1986 = await urban1986.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: naivasha,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2000 = await urban2000.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: naivasha,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const urbanCount1986 = stats1986.NDVI_sum || 0;
  const totalCount1986 = stats1986.NDVI_count || 0;
  const urbanCount2000 = stats2000.NDVI_sum || 0;
  const totalCount2000 = stats2000.NDVI_count || 0;

  console.log(`1986 Valid Pixels: ${totalCount1986}, Urban: ${urbanCount1986}`);
  console.log(`2000 Valid Pixels: ${totalCount2000}, Urban: ${urbanCount2000}`);

  if (totalCount1986 === 0 || totalCount2000 === 0) {
    console.log('No valid pixels after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  if (urbanCount1986 === null || urbanCount2000 === null) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Compare urban areas
  const urbanArea1986 = urbanCount1986 * 9; // 3000m scale = 9 km²/pixel
  const urbanArea2000 = urbanCount2000 * 9;

  console.log(`Urban Area 1986: ${urbanArea1986.toFixed(2)} km²`);
  console.log(`Urban Area 2000: ${urbanArea2000.toFixed(2)} km²`);

  if (urbanArea2000 > urbanArea1986) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
